[CmdletBinding()]
param(
    [string]$Fqdn,
    [int]$Port = 8443,
    [object]$Access,
    [string]$WatcherUser,
    [switch]$RenewCertificate
)
$ErrorActionPreference = 'Stop'
$base = 'C:\bandit-ai'
$agent = "$base\agent"
$state = "$agent\state"
$control = "$base\control"
$powerShell = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe"
$appid = '{5D47F1C8-0B8C-4D9A-B7A1-4E29E4D42A01}'

# test-install-agent.ps1 checks these payloads against the source files.
$embedded = @{
    'agent.ps1' = ''
    'ui.html' = ''
}

function Assert-Admin {
    $p = [Security.Principal.WindowsPrincipal][Security.Principal.WindowsIdentity]::GetCurrent()
    if (-not $p.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) { throw 'Run from an elevated Windows PowerShell.' }
}
function Assert-NoLinks([string]$Path) {
    $cursor = [IO.Path]::GetFullPath($Path)
    while ($cursor) {
        $item = Get-Item -LiteralPath $cursor -Force -ErrorAction SilentlyContinue
        if ($item -and (($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0)) { throw "Refusing reparse point: $cursor" }
        $parent = [IO.Path]::GetDirectoryName($cursor)
        if ($parent -eq $cursor) { break }
        $cursor = $parent
    }
}
function Set-ExactAcl([string]$Path, [string]$ReadSid = '') {
    $item = Get-Item -LiteralPath $Path -Force
    $acl = if ($item.PSIsContainer) { New-Object Security.AccessControl.DirectorySecurity } else { New-Object Security.AccessControl.FileSecurity }
    $acl.SetAccessRuleProtection($true, $false)
    $admin = New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')
    $acl.SetOwner($admin)
    $inherit = if ($item.PSIsContainer) { [Security.AccessControl.InheritanceFlags]'ContainerInherit,ObjectInherit' } else { [Security.AccessControl.InheritanceFlags]::None }
    foreach ($sid in 'S-1-5-32-544','S-1-5-18') {
        $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($sid)), 'FullControl', $inherit, 'None', 'Allow')))
    }
    if ($ReadSid) {
        $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule((New-Object Security.Principal.SecurityIdentifier($ReadSid)), 'ReadAndExecute', $inherit, 'None', 'Allow')))
    }
    Set-Acl -LiteralPath $Path -AclObject $acl
}
function Remove-BroadWrite([string]$Path) {
    $item = Get-Item -LiteralPath $Path -Force
    $acl = Get-Acl -LiteralPath $Path
    $acl.SetAccessRuleProtection($true, $true)
    $acl.SetOwner((New-Object Security.Principal.SecurityIdentifier('S-1-5-32-544')))
    foreach ($rule in $acl.GetAccessRules($true, $true, [Security.Principal.SecurityIdentifier])) {
        $sid = $rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value
        $writeBits = [Security.AccessControl.FileSystemRights]'WriteData,AppendData,WriteAttributes,WriteExtendedAttributes,Delete,DeleteSubdirectoriesAndFiles,ChangePermissions,TakeOwnership'
        $remove = [Security.AccessControl.FileSystemRights]'Delete,DeleteSubdirectoriesAndFiles,ChangePermissions,TakeOwnership'
        if ($sid -in @('S-1-5-11','S-1-5-32-545')) { $remove = $writeBits }
        if ($sid -notin @('S-1-5-32-544','S-1-5-18') -and $rule.AccessControlType -eq 'Allow' -and (($rule.FileSystemRights -band $remove) -ne 0)) {
            $acl.RemoveAccessRuleSpecific($rule)
            $kept = $rule.FileSystemRights -band (-bnot $remove)
            if ($kept -ne 0) { $acl.AddAccessRule((New-Object Security.AccessControl.FileSystemAccessRule($rule.IdentityReference, $kept, $rule.InheritanceFlags, $rule.PropagationFlags, $rule.AccessControlType))) }
        }
    }
    Set-Acl -LiteralPath $Path -AclObject $acl
}
function Write-AtomicBytes([string]$Path, [byte[]]$Bytes) {
    Assert-NoLinks $Path
    $tmp = "$Path.$([Guid]::NewGuid().ToString('N')).tmp"
    try {
        $stream = [IO.File]::Open($tmp, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::None)
        try { $stream.Write($Bytes, 0, $Bytes.Length) } finally { $stream.Dispose() }
        Assert-NoLinks $tmp
        Move-Item -LiteralPath $tmp -Destination $Path -Force
    } finally { if (Test-Path -LiteralPath $tmp) { Remove-Item -LiteralPath $tmp -Force -ErrorAction SilentlyContinue } }
}
function Protect-Tree([string]$Path, [string]$ReadSid = '') {
    Assert-NoLinks $Path
    Set-ExactAcl $Path $ReadSid
    foreach ($item in Get-ChildItem -LiteralPath $Path -Force -ErrorAction Stop) {
        Assert-NoLinks $item.FullName
        if ($item.PSIsContainer) { Protect-Tree $item.FullName $ReadSid }
        else { Set-ExactAcl $item.FullName $ReadSid }
    }
}
function Resolve-Access([object]$Value) {
    if ($null -eq $Value) { throw 'Access is required.' }
    $obj = if ($Value -is [string]) { ConvertFrom-Json -InputObject $Value } else { $Value }
    $out = [ordered]@{}
    $properties = if ($obj -is [System.Collections.IDictionary]) { @($obj.GetEnumerator() | ForEach-Object { [pscustomobject]@{ Name = $_.Key; Value = $_.Value } }) } else { @($obj.PSObject.Properties) }
    foreach ($p in $properties) {
        if ([string]$p.Name -notmatch '^[A-Za-z0-9._:-]+$' -or $p.Value -isnot [string] -or $p.Value -cnotin @('self','operator','owner')) { throw 'Access must map StableID values to self, operator, or owner.' }
        $out[[string]$p.Name] = [string]$p.Value
    }
    if (-not $out.Count) { throw 'Access cannot be empty.' }
    return $out
}
function Get-Config {
    Assert-NoLinks "$agent\config.json"
    if (-not (Test-Path -LiteralPath "$agent\config.json")) { throw 'Agent config is missing.' }
    return (Get-Content -LiteralPath "$agent\config.json" -Raw | ConvertFrom-Json)
}
function Convert-CertificatePfx([string]$CertPath, [string]$KeyPath) {
    # .NET Framework's CNG import takes PKCS#8; wrap a SEC1 EC key using the certificate's curve OID.
    if (-not ('BanditCertificate' -as [type])) {
        Add-Type -TypeDefinition @'
using System;
using System.IO;
using System.Text.RegularExpressions;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;
public static class BanditCertificate {
    static byte[] Join(params byte[][] parts) {
        using (var s = new MemoryStream()) {
            foreach (var p in parts) s.Write(p, 0, p.Length);
            return s.ToArray();
        }
    }
    static byte[] Der(byte tag, byte[] data) {
        if (data.Length > 65535) throw new Exception("DER too large");
        byte[] length = data.Length < 128 ? new byte[] {(byte)data.Length} :
            (data.Length < 256 ? new byte[] {0x81, (byte)data.Length} : new byte[] {0x82, (byte)(data.Length >> 8), (byte)data.Length});
        return Join(new byte[] {tag}, length, data);
    }
    public static byte[] Convert(string certPem, string keyPem) {
        var certMatch = Regex.Match(certPem, @"-----BEGIN CERTIFICATE-----\s*([A-Za-z0-9+/=\s]+?)-----END CERTIFICATE-----");
        var keyMatch = Regex.Match(keyPem, @"-----BEGIN (EC PRIVATE KEY|PRIVATE KEY)-----\s*([A-Za-z0-9+/=\s]+?)-----END \1-----");
        if (!certMatch.Success || !keyMatch.Success) throw new Exception("Unsupported certificate or private key PEM");
        using (var cert = new X509Certificate2(System.Convert.FromBase64String(certMatch.Groups[1].Value))) {
            byte[] key = System.Convert.FromBase64String(keyMatch.Groups[2].Value);
            if (cert.PublicKey.Oid.Value != "1.2.840.10045.2.1") throw new Exception("Expected Tailscale ECDSA certificate");
            if (keyMatch.Groups[1].Value == "EC PRIVATE KEY") {
                byte[] ecOid = new byte[] {0x06,0x07,0x2a,0x86,0x48,0xce,0x3d,0x02,0x01};
                key = Der(0x30, Join(new byte[] {0x02,0x01,0x00}, Der(0x30, Join(ecOid, cert.PublicKey.EncodedParameters.RawData)), Der(0x04, key)));
            }
            try {
                using (var cng = CngKey.Import(key, CngKeyBlobFormat.Pkcs8PrivateBlob))
                {
                    cng.SetProperty(new CngProperty("Export Policy", BitConverter.GetBytes(3), CngPropertyOptions.None));
                    using (var ec = new ECDsaCng(cng))
                    using (var paired = ECDsaCertificateExtensions.CopyWithPrivateKey(cert, ec)) {
                        return paired.Export(X509ContentType.Pfx, "");
                    }
                }
            } finally { Array.Clear(key, 0, key.Length); }
        }
    }
}
'@
    }
    return [BanditCertificate]::Convert([IO.File]::ReadAllText($CertPath), [IO.File]::ReadAllText($KeyPath))
}
function Invoke-CertificateBinding([string]$Name, [int]$Number, [string]$TailscalePath) {
    Assert-NoLinks $state
    $cert = "$state\agent.crt"
    $key = "$state\agent.key"
    $pfx = "$state\agent.pfx"
    Assert-NoLinks $cert; Assert-NoLinks $key; Assert-NoLinks $pfx
    & $TailscalePath cert --cert-file $cert --key-file $key $Name
    if ($LASTEXITCODE -ne 0) { throw 'tailscale cert failed.' }
    Assert-NoLinks $cert; Assert-NoLinks $key
    Write-AtomicBytes $pfx (Convert-CertificatePfx $cert $key)
    $certObject = Import-PfxCertificate -FilePath $pfx -CertStoreLocation Cert:\LocalMachine\My -ErrorAction Stop
    if (-not $certObject.HasPrivateKey) { throw 'Imported certificate has no private key' }
    $thumb = $certObject.Thumbprint.Replace(' ','').ToUpperInvariant()
    & "$env:WINDIR\System32\netsh.exe" http delete sslcert "hostnameport=$Name`:$Number" 2>$null
    & "$env:WINDIR\System32\netsh.exe" http add sslcert "hostnameport=$Name`:$Number" "certhash=$thumb" "appid=$appid" certstorename=MY
    if ($LASTEXITCODE -ne 0) { throw 'netsh SSL binding failed.' }
}
function Register-AgentTasks([string]$Name, [int]$Number) {
    $action = New-ScheduledTaskAction -Execute $powerShell -Argument '-NoProfile -ExecutionPolicy Bypass -File C:\bandit-ai\agent\agent.ps1'
    $trigger = New-ScheduledTaskTrigger -AtStartup
    $principal = New-ScheduledTaskPrincipal -UserId 'SYSTEM' -LogonType ServiceAccount -RunLevel Highest
    $settings = New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::Zero) -RestartCount 999 -RestartInterval (New-TimeSpan -Minutes 1) -StartWhenAvailable
    Register-ScheduledTask -TaskName 'bandit-agent' -Action $action -Trigger $trigger -Principal $principal -Settings $settings -Force | Out-Null
    $renewAction = New-ScheduledTaskAction -Execute $powerShell -Argument "-NoProfile -ExecutionPolicy Bypass -File C:\bandit-ai\agent\install-agent.ps1 -RenewCertificate -Fqdn $Name -Port $Number"
    $renewTrigger = New-ScheduledTaskTrigger -Daily -At 03:17
    Register-ScheduledTask -TaskName 'bandit-agent-renew' -Action $renewAction -Trigger $renewTrigger -Principal $principal -Settings (New-ScheduledTaskSettingsSet -ExecutionTimeLimit ([TimeSpan]::FromHours(1))) -Force | Out-Null
}
function Install-Agent {
    if ($Fqdn -notmatch '^(?=.{1,253}$)[A-Za-z0-9](?:[A-Za-z0-9.-]*[A-Za-z0-9])?$' -or $Fqdn -notmatch '\.') { throw 'Fqdn is invalid.' }
    $Fqdn = $Fqdn.ToLowerInvariant()
    if ($Port -lt 1 -or $Port -gt 65535) { throw 'Port is invalid.' }
    if (-not $WatcherUser) { throw 'WatcherUser is required.' }
    $watcherSid = ([Security.Principal.NTAccount]$WatcherUser).Translate([Security.Principal.SecurityIdentifier]).Value
    $accessMap = Resolve-Access $Access
    foreach ($p in @($base,$agent,$state,$control,"$agent\agent.ps1","$agent\ui.html","$agent\config.json","$agent\access.json")) { Assert-NoLinks $p }
    New-Item -ItemType Directory -Force -Path $base,$agent,$state,$control | Out-Null
    foreach ($p in @($base,$agent,$state,$control)) { Assert-NoLinks $p }
    Remove-BroadWrite $base
    Protect-Tree $agent
    Protect-Tree $control $watcherSid
    Write-AtomicBytes "$agent\config.json" ([Text.Encoding]::ASCII.GetBytes((@{ fqdn=$Fqdn; port=$Port; tailscale=(Get-Command tailscale.exe -ErrorAction Stop).Source } | ConvertTo-Json -Compress)))
    Write-AtomicBytes "$agent\access.json" ([Text.Encoding]::ASCII.GetBytes(($accessMap | ConvertTo-Json -Compress)))
    Set-ExactAcl "$agent\config.json"
    Set-ExactAcl "$agent\access.json"
    foreach ($name in $embedded.Keys) {
        $path = "$agent\$name"
        Write-AtomicBytes $path ([Convert]::FromBase64String($embedded[$name]))
        Set-ExactAcl $path
    }
    if ([IO.Path]::GetFullPath($PSCommandPath) -ne "$agent\install-agent.ps1") {
        Write-AtomicBytes "$agent\install-agent.ps1" ([IO.File]::ReadAllBytes($PSCommandPath))
    }
    Set-ExactAcl "$agent\install-agent.ps1"
    $tailscale = (Get-Content "$agent\config.json" -Raw | ConvertFrom-Json).tailscale
    Invoke-CertificateBinding $Fqdn $Port $tailscale
    Remove-NetFirewallRule -Name 'bandit-agent' -ErrorAction SilentlyContinue
    New-NetFirewallRule -Name 'bandit-agent' -DisplayName 'bandit-agent tailnet' -Direction Inbound -Action Allow -Protocol TCP -LocalPort $Port -RemoteAddress '100.64.0.0/10' -InterfaceAlias 'Tailscale' -Profile Any | Out-Null
    Register-AgentTasks $Fqdn $Port
    Start-ScheduledTask -TaskName 'bandit-agent'
}
function Renew-Certificate {
    $cfg = Get-Config
    Invoke-CertificateBinding $cfg.fqdn ([int]$cfg.port) $cfg.tailscale
}

Assert-Admin
if ($RenewCertificate) { Renew-Certificate; exit 0 }
$old = Get-ScheduledTask -TaskName 'bandit-agent' -ErrorAction SilentlyContinue
foreach ($p in @($base,$agent,$state,$control)) { Assert-NoLinks $p }
if ($old) { Stop-ScheduledTask -TaskName 'bandit-agent' -ErrorAction SilentlyContinue }
if (Get-ScheduledTask -TaskName 'bandit-agent-renew' -ErrorAction SilentlyContinue) { Stop-ScheduledTask -TaskName 'bandit-agent-renew' -ErrorAction SilentlyContinue }
foreach ($taskName in 'bandit-agent','bandit-agent-renew') {
    $deadline = [datetime]::UtcNow.AddSeconds(10)
    while ((Get-ScheduledTask -TaskName $taskName -ErrorAction SilentlyContinue).State -eq 'Running') {
        if ([datetime]::UtcNow -ge $deadline) { throw "Task did not stop: $taskName" }
        Start-Sleep -Milliseconds 100
    }
}
Install-Agent
